
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_case21_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_case21", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.285104785892305e+00, -3.222942372528710e+00, -3.135910897599523e+00, -3.015506536456760e+00, -2.851776181741928e+00, -2.634594670537067e+00, -2.356656047194674e+00, -2.018816541383812e+00, -1.636632576592181e+00, -1.236875772684473e+00, -8.348413706770786e-01, -5.724072256228725e-01, -4.980722147136507e-01, -4.104723966988955e-01, -2.995009659117617e-01, -1.911892101806966e-01, -9.946721129680716e-02, -3.588327556022617e-02, -7.791562979662462e-03, -8.761026606781794e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


